// Abdominal wall in section: skin + fat blocks either side of the wound; fascia closed beneath.
const ST = 196, SB = 236, FT = 384, FB = 406, X0 = 52, X1 = 588;
const RED = "#c0392b", TEAL = "#2a9d8f", SUT = "#1f3b57";
const OPEN = {lt: 268, lb: 312, rt: 372, rb: 328}, SHUT = {lt: 319.2, lb: 319.2, rt: 320.8, rb: 320.8};
const DAYS = [2900, 3500, 4100];                 // Day 1, 2, 3 dressing changes
const TL0 = 150, TL1 = 450, TLY = 484;           // timeline Day 0..3
let el = {};
function txt(api, parent, s, attrs) {
  const t = api.el("text", Object.assign({"font-family": "system-ui,sans-serif", "font-weight": 700, "font-size": 18}, attrs), parent);
  t.textContent = s; return t;
}
function chip(api, parent, s, cx, cy, w, color, stroke) {
  const g = api.el("g", {}, parent);
  api.el("rect", {x: cx - w / 2, y: cy - 17, width: w, height: 34, rx: 17, fill: "#ffffff", stroke: stroke, "stroke-width": 2, filter: "url(#chipShadow)"}, g);
  txt(api, g, s, {x: cx, y: cy + 1, "text-anchor": "middle", "dominant-baseline": "central", fill: color});
  return g;
}
const xAt = (top, bot, y) => top + (bot - top) * (y - ST) / (FT - ST);
function setup(api) {
  const sec = api.$("#sec"), top = api.$("#top");
  el.lFat = api.el("polygon", {fill: "url(#fatG)", stroke: "#e2c25c", "stroke-width": 1.5}, sec);
  el.rFat = api.el("polygon", {fill: "url(#fatG)", stroke: "#e2c25c", "stroke-width": 1.5}, sec);
  // fat lobules (static, clipped away from the wound by staying outside x 250..390)
  const rnd = api.random(7);
  el.lob = api.el("g", {fill: "none", stroke: "#e6c766", "stroke-width": 1.4}, sec);
  for (let i = 0; i < 26; i++) {
    const left = i % 2 === 0, x = left ? 70 + rnd() * 190 : 390 + rnd() * 180, y = 256 + rnd() * 112;
    api.el("circle", {cx: x, cy: y, r: 9 + rnd() * 6}, el.lob);
  }
  el.lSkin = api.el("polygon", {fill: "url(#skinG)", stroke: "#d99a78", "stroke-width": 1.5}, sec);
  el.rSkin = api.el("polygon", {fill: "url(#skinG)", stroke: "#d99a78", "stroke-width": 1.5}, sec);
  el.bed = api.el("path", {fill: "none", stroke: "#ea9c95", "stroke-width": 7, "stroke-linejoin": "round", "stroke-linecap": "round"}, sec);
  // contamination: dots stuck to the wound walls and floor, cleared over 3 dressing changes
  el.dots = [];
  const r2 = api.random(21);
  for (let i = 0; i < 15; i++) {
    const side = i % 3, v = 0.12 + r2() * 0.8, u = r2();
    el.dots.push({side: side, v: v, u: u, day: i % 3, k: i, c: api.el("circle", {r: 5.5, fill: RED, stroke: "#ffffff", "stroke-width": 1.6}, sec)});
  }
  // fascia suture (closed at operation)
  api.el("ellipse", {cx: 320, cy: 395, rx: 13, ry: 9, fill: "none", stroke: SUT, "stroke-width": 3}, sec);
  api.el("circle", {cx: 320, cy: 386, r: 3.5, fill: SUT}, sec);
  // skin suture (delayed closure)
  el.skinSut = api.el("path", {d: "M 320 194 C 302 194 301 222 304 246 C 308 270 332 270 336 246 C 339 222 338 194 320 194 Z", fill: "none", stroke: SUT, "stroke-width": 3.2, "stroke-linecap": "round", pathLength: 1}, sec);
  el.knot = api.el("path", {d: "M 312 186 L 320 194 L 328 186", fill: "none", stroke: SUT, "stroke-width": 3, "stroke-linecap": "round", "stroke-linejoin": "round"}, top);
  // dressing pad over the open wound
  el.pad = api.el("g", {}, top);
  api.el("rect", {x: 232, y: 174, width: 176, height: 26, rx: 8, fill: "url(#gauze)", stroke: "#9fb6bd", "stroke-width": 2, filter: "url(#chipShadow)"}, el.pad);
  txt(api, el.pad, "Dressing", {x: 418, y: 193, fill: "@muted", stroke: "#ffffff", "stroke-width": 5, "stroke-linejoin": "round", "paint-order": "stroke"});
  // layer labels
  const lab = {stroke: "#ffffff", "stroke-width": 5, "stroke-linejoin": "round", "paint-order": "stroke", fill: "@ink"};
  txt(api, top, "Skin", Object.assign({x: 70, y: 220}, lab));
  txt(api, top, "Fat", Object.assign({x: 70, y: 310}, lab));
  txt(api, top, "Fascia closed", Object.assign({}, lab, {x: 572, y: 401, "text-anchor": "end", fill: TEAL}));
  // status chips above the wound
  el.cOpen = chip(api, top, "Skin left open", 320, 150, 170, RED, "#f0b7ae");
  el.cClean = chip(api, top, "Wound clean", 320, 150, 156, TEAL, "#b9e2dc");
  el.cShut = chip(api, top, "✓ Skin closed", 320, 150, 156, TEAL, "#b9e2dc");
  // day timeline
  api.el("line", {x1: TL0, y1: TLY, x2: TL1, y2: TLY, stroke: "#dbe6e7", "stroke-width": 6, "stroke-linecap": "round"}, top);
  el.prog = api.el("line", {x1: TL0, y1: TLY, x2: TL0, y2: TLY, stroke: TEAL, "stroke-width": 6, "stroke-linecap": "round"}, top);
  el.dayLab = [];
  for (let d = 0; d <= 3; d++) {
    const x = TL0 + (TL1 - TL0) * d / 3;
    api.el("circle", {cx: x, cy: TLY, r: 6, fill: "#ffffff", stroke: "#b6c9cb", "stroke-width": 2.5}, top);
    el.dayLab.push(txt(api, top, "Day " + d, {x: x, y: TLY + 30, "text-anchor": "middle", fill: "@muted"}));
  }
  el.mark = api.el("circle", {r: 11, fill: TEAL, stroke: "#ffffff", "stroke-width": 3, filter: "url(#chipShadow)"}, top);
  el.tick = txt(api, top, "✓", {x: TL1 + 26, y: TLY + 7, fill: TEAL, "font-size": 24, "font-weight": 800});
}
function vis(api, node, k) { api.set(node, {opacity: k, display: k > 0.001 ? "inline" : "none"}); }
function render(t, api) {
  const close = api.seg(t, 4750, 5450, "ease_in_out");
  const e = {lt: api.lerp(OPEN.lt, SHUT.lt, close), lb: api.lerp(OPEN.lb, SHUT.lb, close),
             rt: api.lerp(OPEN.rt, SHUT.rt, close), rb: api.lerp(OPEN.rb, SHUT.rb, close)};
  const lS = xAt(e.lt, e.lb, SB), rS = xAt(e.rt, e.rb, SB);
  const P = a => a.map(p => p[0].toFixed(1) + "," + p[1].toFixed(1)).join(" ");
  api.set(el.lFat, {points: P([[X0, SB], [lS, SB], [e.lb, FT], [X0, FT]])});
  api.set(el.rFat, {points: P([[X1, SB], [rS, SB], [e.rb, FT], [X1, FT]])});
  api.set(el.lSkin, {points: P([[X0, ST], [e.lt, ST], [lS, SB], [X0, SB]])});
  api.set(el.rSkin, {points: P([[X1, ST], [e.rt, ST], [rS, SB], [X1, SB]])});
  api.set(el.bed, {d: "M " + (e.lt + 3) + " " + (SB + 2) + " L " + (e.lb + 3) + " " + (FT - 3) + " L " + (e.rb - 3) + " " + (FT - 3) + " L " + (e.rt - 3) + " " + (SB + 2)});
  vis(api, el.bed, 1 - api.seg(t, 4800, 5300));
  // daily dressing: pad lifts and is replaced at each day mark; one third of the dirt goes each time
  const padIn = api.seg(t, 2300, 2650, "ease_out"), padOut = api.seg(t, 4600, 4850);
  let lift = 0;
  DAYS.forEach(d => { lift = Math.max(lift, Math.sin(Math.PI * api.seg(t, d - 200, d + 200, "linear"))); });
  vis(api, el.pad, padIn * (1 - padOut) * (1 - 0.2 * lift));
  api.set(el.pad, {transform: "translate(0 " + (-(1 - padIn) * 16 - lift * 12 - padOut * 12).toFixed(1) + ")"});
  el.dots.forEach(o => {
    const gone = api.seg(t, DAYS[o.day] - 120, DAYS[o.day] + 180);
    let x, y;
    if (o.side === 2) { y = FT - 9; x = api.lerp(e.lb + 9, e.rb - 9, o.u); }
    else { y = api.lerp(SB + 10, FT - 12, o.v); x = o.side === 0 ? xAt(e.lt, e.lb, y) + 8 : xAt(e.rt, e.rb, y) - 8; }
    api.set(o.c, {cx: x, cy: y});
    const pop = api.seg(t, 200 + o.k * 70, 500 + o.k * 70, "back_out");
    api.set(o.c, {r: (5.5 * pop).toFixed(2)});
    vis(api, o.c, (pop > 0 ? 1 : 0) * (1 - gone));
  });
  // skin suture draws on once the edges meet
  const sut = api.seg(t, 5150, 5650, "ease_out");
  api.set(el.skinSut, {"stroke-dasharray": sut.toFixed(4) + " 1.001"});
  vis(api, el.skinSut, sut > 0 ? 1 : 0);
  vis(api, el.knot, api.seg(t, 5550, 5750));
  // chips
  vis(api, el.cOpen, api.seg(t, 250, 600) * (1 - api.seg(t, 4000, 4200)));
  vis(api, el.cClean, api.seg(t, 4150, 4400) * (1 - api.seg(t, 5100, 5300)));
  const sk = api.seg(t, 5300, 5600, "back_out");
  vis(api, el.cShut, api.seg(t, 5300, 5450));
  api.set(el.cShut, {transform: "translate(320 150) scale(" + (0.8 + 0.2 * sk).toFixed(3) + ") translate(-320 -150)"});
  // day counter
  let day = 0;
  DAYS.forEach((d, i) => { day += api.seg(t, d - 300, d, "ease_in_out"); });
  const mx = TL0 + (TL1 - TL0) * day / 3;
  api.set(el.mark, {cx: mx, cy: TLY});
  api.set(el.prog, {x2: mx});
  el.dayLab.forEach((n, i) => api.set(n, {fill: Math.round(day) === i ? TEAL : "@muted"}));
  vis(api, el.tick, api.seg(t, 5400, 5700));
}
